<script setup lang="ts">
import { motion } from "motion-v";
import { useReducedMotion } from "../../../lib/composables";
import { cn } from "../../../lib/utils";
import type { SliderOptions } from "./useSlider";
import { useInlineSlider } from "./inline-state";
const props = withDefaults(defineProps<SliderOptions & { label: string; format?: (v: number) => string; showTicks?: boolean }>(), { format: String, showTicks: true });
const emit = defineEmits(["update:modelValue", "change", "valueCommit"]);
const reduced = useReducedMotion();
const { current, trackRef, sliderRef, sliderProps, labelRef, readoutRef, dragging, handleX, fillX, stemOpacity, capTop, capBottom, ticks, down, move, end, key } = useInlineSlider(props, emit, reduced);
</script>
<template><div ref="trackRef" @pointerdown="down" @pointermove="move" @pointerup="end" @pointercancel="end" @lostpointercapture="end" :class="cn('relative h-10 w-full touch-none select-none overflow-hidden rounded-lg bg-muted', disabled ? 'pointer-events-none opacity-50' : 'cursor-grab active:cursor-grabbing')"><div aria-hidden="true" class="pointer-events-none absolute inset-x-[2px] inset-y-0 overflow-hidden rounded-lg"><motion.div class="absolute inset-0 rounded-lg bg-foreground/15" :style="{ x: fillX }" /></div><div aria-hidden="true" class="pointer-events-none absolute inset-0 text-foreground"><span ref="labelRef" class="absolute left-5 top-1/2 max-w-[40%] -translate-y-1/2 truncate text-sm font-medium leading-5">{{ label }}</span><span ref="readoutRef" class="absolute right-5 top-1/2 max-w-[40%] -translate-y-1/2 truncate text-[13px] font-semibold leading-[18px] tracking-tight tabular-nums">{{ format(current) }}</span><span v-for="left in ticks" :key="left" class="absolute top-1/2 size-1 -translate-y-1/2 rounded-full bg-foreground/25" :style="{ left: `${left}px` }" /></div><motion.div aria-hidden="true" :animate="reduced ? undefined : { scaleY: dragging ? 1.35 : 1 }" :transition="{ type: 'spring', stiffness: 500, damping: 14, mass: .7 }" class="pointer-events-none absolute left-0 top-2 h-6 w-1 text-foreground" :style="{ x: handleX }"><motion.span class="absolute top-0 size-1 rounded-full bg-current" :style="{ y: reduced ? 0 : capTop }" /><motion.span class="absolute inset-y-0 w-1 rounded-full bg-current" :style="{ opacity: stemOpacity }" /><motion.span class="absolute bottom-0 size-1 rounded-full bg-current" :style="{ y: reduced ? 0 : capBottom }" /></motion.div><button ref="sliderRef" type="button" v-bind="{ ...sliderProps, onKeydown: undefined, 'aria-label': ariaLabel ?? label, 'aria-valuetext': formatValueText?.(current) ?? format(current) }" @keydown="key" class="absolute inset-0 cursor-inherit touch-none rounded-lg border-0 outline-none" /></div></template>
